(()=>{const menu=document.querySelector('.menu'),mobile=document.querySelector('#mobile-nav');function closeMenu(){if(!menu||!mobile)return;mobile.hidden=true;menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu');document.body.classList.remove('menu-open')}menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';mobile.hidden=!open;menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');document.body.classList.toggle('menu-open',open)});mobile?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();document.querySelectorAll('.shop-nav[open]').forEach(d=>d.open=false)}});document.addEventListener('click',e=>document.querySelectorAll('.shop-nav[open]').forEach(d=>{if(!d.contains(e.target))d.open=false}));document.querySelectorAll('.catalog-section').forEach(section=>{const grid=section.querySelector('.product-grid'),query=section.querySelector('.catalog-query'),sort=section.querySelector('.catalog-sort');if(!grid||!query)return;const cards=[...grid.children],count=section.querySelector('.catalog-count'),empty=section.querySelector('.catalog-empty');let limit=24;const more=document.createElement('button');more.className='catalog-more';more.type='button';more.textContent='Show more selections ↓';grid.after(more);query.value=new URLSearchParams(location.search).get('q')||'';function render(reset){if(reset)limit=24;let selected=cards.filter(c=>c.dataset.name.includes(query.value.trim().toLowerCase()));if(sort.value==='low')selected.sort((a,b)=>+a.dataset.price-+b.dataset.price);if(sort.value==='high')selected.sort((a,b)=>+b.dataset.price-+a.dataset.price);if(sort.value==='name')selected.sort((a,b)=>a.dataset.name.localeCompare(b.dataset.name));cards.forEach(c=>c.hidden=true);selected.forEach((c,i)=>{grid.append(c);c.hidden=i>=limit});count.textContent=`${Math.min(limit,selected.length)} of ${selected.length} selections`;empty.hidden=selected.length>0;more.hidden=selected.length<=limit}query.addEventListener('input',()=>render(true));sort.addEventListener('change',()=>render(true));section.querySelector('form')?.addEventListener('submit',e=>e.preventDefault());more.addEventListener('click',()=>{limit+=24;render(false)});render(true)});if(window.gsap&&window.ScrollTrigger&&!matchMedia('(prefers-reduced-motion: reduce)').matches){gsap.registerPlugin(ScrollTrigger);gsap.from('.inner-page .page-intro .eyebrow,.inner-page .page-intro h1,.inner-page .intro-line>p',{y:24,opacity:0,duration:.8,stagger:.09,ease:'power2.out'});}const service=new URLSearchParams(location.search).get('service');if(['Essential','Annual','Deluxe'].includes(service)){const notice=document.querySelector('.booking-notice');if(notice){const p=document.createElement('p');p.textContent=`Considering the ${service} tune-up? Mention it when arranging your appointment below.`;notice.append(p)}}})();
